class StormWeather{
 constructor(random=Math.random){this.random=random;this.reset();}
 reset(){this.wait=5+this.random()*5;this.flash=0;this.thunder=-1;this.strength=0;}
 update(dt,zone,transition=false){if(zone<3||zone===5||zone>=7||transition){this.flash=0;this.thunder=-1;return false;}this.flash=Math.max(0,this.flash-dt);let rumble=false;if(this.thunder>=0){this.thunder-=dt;if(this.thunder<=0){this.thunder=-1;rumble=true;}}this.wait-=dt;if(this.wait<=0){this.flash=.65;this.strength=zone===6?1:.65;this.thunder=.65+this.random()*1.1;this.wait=(zone===6?10:15)+this.random()*12;}return rumble;}
 get light(){return this.flash>0?Math.sin(this.flash/.65*Math.PI)*.13*this.strength:0;}
}
